  "implementation": "def solve(case):
    # Extract payload fields
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])

    # Build structures
    id_to_node = {}
    children = {}
    for node in nodes:
        nid = node['id']
        id_to_node[nid] = node
        children.setdefault(nid, [])
    for node in nodes:
        parent = node.get('parent')
        if parent is not None:
            children.setdefault(parent, []).append(node['id'])

    # Find root (parent is None)
    root_id = None
    for node in nodes:
        if node.get('parent') is None:
            root_id = node['id']
            break

    # Precompute subtree node sets and required symbol counts
    subtree_nodes = {}
    subtree_counts = {}
    # Use postorder (depth descending ensures children processed before parent, but we have depth field; simpler: DFS recursion)
    def dfs(nid):
        node_set = {nid}
        counts = {}
        node = id_to_node[nid]
        if node['symbol'] in required_symbols:
            counts[node['symbol']] = 1
        for child_id in children.get(nid, []):
            child_set, child_counts = dfs(child_id)
            node_set.update(child_set)
            for sym, cnt in child_counts.items():
                counts[sym] = counts.get(sym, 0) + cnt
        subtree_nodes[nid] = node_set
        subtree_counts[nid] = counts
        return node_set, counts

    if root_id is not None:
        dfs(root_id)

    # Global required symbol counts
    global_counts = dict(subtree_counts[root_id]) if root_id else {}

    # Sort nodes: deeper first, then by ID (string)
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    retained = set(id_to_node.keys())
    removed_order = []

    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained:
            continue
        if not node['removable']:
            continue
        if node['parent'] is None:  # root
            continue
        if node['symbol'] in required_symbols:
            continue
        # Check if any child is still retained
        child_ids = children.get(nid, [])
        has_retained_child = any(cid in retained for cid in child_ids)
        if has_retained_child:
            continue
        # Check required symbol availability after removal
        counts_here = subtree_counts[nid]
        ok = True
        for sym in required_symbols:
            cnt_here = counts_here.get(sym, 0)
            if cnt_here > 0 and global_counts.get(sym, 0) - cnt_here == 0:
                ok = False
                break
        if not ok:
            continue
        # Remove entire subtree
        to_remove = subtree_nodes[nid]
        retained.difference_update(to_remove)
        # Update global counts
        for sym, cnt in counts_here.items():
            global_counts[sym] -= cnt
        removed_order.append(nid)

    retained_ids = sorted(retained)
    return {
        "removed_node_ids": removed_order,
        "retained_node_ids": retained_ids
    }"
}
